// bookshelf/shelf.js — the 3D shelf on /bookshelf/ (generated by Dispatches; do not edit by hand).
import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

const PLANK = 0.75;        // shelf board thickness, inches
const DEPTH = 11;          // how deep the bottom board is, inches
const SETBACK = 1.5;      // books stand this far back from the board's front edge
const PAD = 0.9;           // margin inside the unit on each side
const PPI = 64;            // spine texture pixels per inch
const SLIDE = 0.5;        // a hovered book slides out this share of its depth (50%)
const YEAR_GAP = 1.5;     // inches of air before the first book of a new year of reading (#40)

// Each cover is loaded ONCE, before the shelf is drawn. Its spine strip and its front face both come from
// that image, so every texture is painted a single time. Swapping textures in after the first frame
// (white spines turning into covers, covers popping in on hover) read as flicker.
function loadCover(src) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => resolve(null);
    img.src = src;
  });
}

// The cover's left strip: the spine's background, the cover's first 10 px (full height).
function stripOf(img) {
  try {
    const iw = img.naturalWidth, ih = img.naturalHeight;
    const sw = Math.min(STRIP_PX, iw);
    const strip = canvasOf(sw, ih);
    strip.getContext('2d').drawImage(img, 0, 0, sw, ih, 0, 0, sw, ih);
    return strip;
  } catch (err) {
    return null;   // a cover that can't be read leaves the plain spine
  }
}

// Loads every cover, reporting progress on the loading line. Never waits longer than 20 s.
async function preload(data, loading) {
  const withCover = data.map((b, i) => (b.cover && !b.marker ? i : -1)).filter((i) => i >= 0);
  const assets = new Array(data.length).fill(null);
  let done = 0;
  loading.textContent = `Loading the shelf… 0 of ${withCover.length}`;
  const job = Promise.all(withCover.map(async (i) => {
    const img = await loadCover(data[i].cover);
    done++;
    loading.textContent = `Loading the shelf… ${done} of ${withCover.length}`;
    if (img) assets[i] = { img, strip: stripOf(img) };
  }));
  await Promise.race([job, new Promise((r) => setTimeout(r, 20000))]);
  return assets;
}

const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function isDark(hex) {
  const n = parseInt(hex.slice(1), 16);
  const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  return (0.299 * r + 0.587 * g + 0.114 * b) / 255 < 0.55;
}

function facts(b) {
  const approx = b.estimated ? '≈ ' : '';
  const kind = b.binding === 'hardcover' ? 'Hardcover' : 'Paperback';
  return `${kind} · ${approx}${b.pages} pages · ${approx}${fmt(b.width)} × ${fmt(b.height)} in`;
}
function fmt(x) { return (Math.round(x * 100) / 100).toString(); }

function canvasOf(w, h) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return c;
}

// The spine: cover colour, cloth or paper grain, a rounded-spine shading,
// the title near the top and the author near the bottom, both reading top to
// bottom (the US convention). Hardcovers get gilt lettering and head/tail bands.
// Typefaces the spines draw in: serif, sans and display faces that ship with macOS and most systems.
const FACES = [
  'Georgia, serif', '"Times New Roman", serif', 'Baskerville, serif', 'Didot, serif',
  'Futura, "Century Gothic", sans-serif', '"Helvetica Neue", Helvetica, Arial, sans-serif',
  '"Avenir Next", Avenir, sans-serif', '"Gill Sans", "Gill Sans MT", sans-serif',
];
// No bold on a spine (Alexis, #42): light, regular and medium. A face without the weight asked for
// falls back to its nearest lighter or regular cut, so the mix only shows where the face has it.
const WEIGHTS = [300, 400, 500];

// A seeded random generator per book, so its tabs fall in the same places on every build.
function seeded(str) {
  let h = 0;
  for (const ch of str) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  h = h || 1;
  return () => {
    h ^= h << 13; h >>>= 0;
    h ^= h >>> 17;
    h ^= h << 5; h >>>= 0;
    return (h % 10000) / 10000;
  };
}

function hashOf(str) {
  let h = 0;
  for (const ch of str) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  return h;
}

function styleFor(id, salt) {
  const h = hashOf(id) + salt * 7919;
  return { f: FACES[h % FACES.length], w: WEIGHTS[(h >>> 3) % WEIGHTS.length] };
}

// The spine title as it is printed: before any colon, without series brackets.
function spineTitle(b) {
  return b.title.split(':')[0].replace(/\([^)]*\)/g, '').trim() || b.title;
}

// Type scales with the title's length: short titles are set large, long ones smaller, never cut.
// Width is measured at 10px and scaled, so the size fills the spine length (capped by its width:
// thicker spines take larger letters).
function titleSize(x, b, w, h, style) {
  x.font = `${style.w} 10px ${style.f}`;
  const perPx = x.measureText(spineTitle(b)).width / 10;
  return Math.max(5, Math.min(w * 0.4, (h * (b.author ? 0.66 : 0.84)) / perPx));
}

// Collection name → the title size its spines share (#42): the middle of what its members would take
// on their own. (The smallest was tried: one long title made the whole set's lettering tiny.) A member
// whose title is too long for that size is set smaller, as on a real set.
const SERIES_SIZE = new Map();
function measureSeries(data) {
  const x = canvasOf(8, 8).getContext('2d');
  const sizes = new Map();
  for (const b of data) {
    if (!b.series) continue;
    const w = Math.max(20, Math.round(b.thickness * PPI));
    const fs = titleSize(x, b, w, Math.round(b.height * PPI), styleFor(b.series, 0));
    sizes.set(b.series, (sizes.get(b.series) || []).concat(fs));
  }
  for (const [name, list] of sizes) {
    list.sort((p, q) => p - q);
    SERIES_SIZE.set(name, list[Math.floor(list.length / 2)]);
  }
}

// The spine's background is the cover's first 10 px (left edge, full height), stretched to the spine.
const STRIP_PX = 10;

function paintSpine(c, b, strip) {
  const w = c.width;
  const h = c.height;
  const x = c.getContext('2d');
  const hard = b.binding === 'hardcover';
  // The lettering colour follows the background it sits on: the cover strip once it has loaded.
  let dark = isDark(b.spine);
  if (strip) {
    const one = canvasOf(1, 1);
    const o = one.getContext('2d');
    o.drawImage(strip, 0, 0, 1, 1);
    const d = o.getImageData(0, 0, 1, 1).data;
    dark = (0.299 * d[0] + 0.587 * d[1] + 0.114 * d[2]) / 255 < 0.55;
  }
  const ink = dark ? '#f6f1e4' : '#1d1b17';
  const gilt = hard ? (dark ? '#e7d18f' : '#6b4f1c') : ink;

  if (strip) {
    x.drawImage(strip, 0, 0, w, h);
  } else {
    // Until its cover arrives a spine is plain white, so the shelf shows at once.
    x.fillStyle = b.cover ? '#f3f0e8' : b.spine;
    x.fillRect(0, 0, w, h);
  }
  for (let i = 0; i < (w * h) / 36; i++) {
    x.fillStyle = Math.random() < 0.5 ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.05)';
    x.fillRect(Math.random() * w, Math.random() * h, 1, 1);
  }
  const round = x.createLinearGradient(0, 0, w, 0);
  round.addColorStop(0, 'rgba(0,0,0,0.05)');
  round.addColorStop(0.45, 'rgba(255,255,255,0.03)');
  round.addColorStop(1, 'rgba(0,0,0,0.07)');
  x.fillStyle = round;
  x.fillRect(0, 0, w, h);
  if (hard) {
    x.fillStyle = gilt;
    x.globalAlpha = 0.55;
    x.fillRect(w * 0.12, h * 0.035, w * 0.76, Math.max(1, h * 0.006));
    x.fillRect(w * 0.12, h * 0.965, w * 0.76, Math.max(1, h * 0.006));
    x.globalAlpha = 1;
  }

  // Text runs along the spine: local x is down the spine, local y runs across it.
  x.save();
  x.translate(w, 0);
  x.rotate(Math.PI / 2);
  x.textBaseline = 'middle';
  x.fillStyle = gilt;
  // Each book gets its own face and weight for the title and the author, chosen from its id,
  // so the shelf varies but a rebuild never reshuffles it.
  // The books of a collection (#42) share one style: it is chosen from the collection's name.
  const tStyle = styleFor(b.series || b.id, 0);
  const aStyle = styleFor(b.series || b.id, 1);
  const titleX = w >= 36 ? w * 0.42 : w * 0.5;
  x.textAlign = 'left';
  // The spine carries the title before any colon, without series brackets: 'Making Money: (Discworld Novel 36)' → 'Making Money'.
  const title = spineTitle(b);
  // A collection's titles share one size; only a title too long for it is set smaller.
  const own = titleSize(x, b, w, h, tStyle);
  const fs = b.series && SERIES_SIZE.get(b.series) ? Math.min(own, SERIES_SIZE.get(b.series)) : own;
  x.font = `${tStyle.w} ${fs}px ${tStyle.f}`;
  // Lightly embossed: a pale edge up-left and a dark edge down-right, so the
  // lettering shows on white, pale or busy spines alike.
  const emboss = (text, px, py) => {
    x.save();
    x.fillStyle = 'rgba(255,255,255,0.8)';
    x.fillText(text, px - 1, py - 1);
    x.fillStyle = 'rgba(0,0,0,0.35)';
    x.fillText(text, px + 1, py + 1);
    x.restore();
    x.fillStyle = gilt;
    x.fillText(text, px, py);
  };
  // On a spine wide enough to carry the author, the title sits slightly off centre (0.58 of the
  // width), leaving the author its own lane; centring it was tried and looked worse (Alexis, #41).
  x.textAlign = 'left';
  emboss(title, h * 0.06, w - titleX);
  if (b.author && w >= 36) {
    // The author stays small and never runs into the title: it shrinks to the space left
    // below the title (the title ends by about 0.72 of the spine's length).
    const room = h * 0.94 - h * 0.74;
    let af = Math.max(5, Math.min(w * 0.2, fs * 0.5));
    x.font = `${aStyle.w} ${af}px ${aStyle.f}`;
    while (af > 5 && x.measureText(b.author).width > room) {
      af -= 0.5;
      x.font = `${aStyle.w} ${af}px ${aStyle.f}`;
    }
    x.textAlign = 'right';
    emboss(b.author, h * 0.94, w - w * 0.76);
  }
  x.restore();
  return c;
}

// The spine, painted once with its cover strip (null = the plain spine colour).
function spineCanvas(b, strip) {
  const w = Math.max(20, Math.round(b.thickness * PPI));
  const h = Math.round(b.height * PPI);
  const c = canvasOf(w, h);
  paintSpine(c, b, strip || null);
  return c;
}

function pageCanvas() {
  // The top of a page block shows each sheet's edge: lines that run across the width and step
  // through the thickness, so the stripes are vertical in the texture (u = thickness).
  const c = canvasOf(64, 8);
  const x = c.getContext('2d');
  x.fillStyle = '#f2ecdb';
  x.fillRect(0, 0, 64, 8);
  for (let px = 0; px < 64; px += 2) {
    x.fillStyle = px % 4 ? 'rgba(120,100,70,0.10)' : 'rgba(120,100,70,0.04)';
    x.fillRect(px, 0, 1, 8);
  }
  return c;
}

function tex(canvas, srgb = true) {
  const t = new THREE.CanvasTexture(canvas);
  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}

const SCREEN_PPI = 50;    // screen pixels per inch: one long bay that scrolls sideways
const SHELF_H = 11.5;     // floor board top to the bay's open top, inches
const FLOOR_T = 1.6;      // the bottom board, thicker than a plank, inches
const TOP_DOWN = 0.2;     // a slight top-down view, as a fraction of the camera's distance, so the page edges show

function main(stage, data, assets) {
  const probe = document.createElement('canvas');
  if (!(probe.getContext('webgl2') || probe.getContext('webgl'))) return;

  // The stage scrolls sideways; a sticky view keeps the canvas in sight while the track sets the length.
  const view = document.createElement('div');
  view.className = 'shelf-view';
  const track = document.createElement('div');
  track.className = 'shelf-track';
  stage.replaceChildren(view, track);


  // An opaque canvas painted in the page's paper colour: a transparent canvas composited its antialiased
  // edges against the page and left dark, dashed fringes along the spines and covers.
  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
  renderer.setClearColor(0xfffff8, 1);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  // No tone mapping: ACES desaturated every cover, so spines read darker and greyer than the book.
  renderer.toneMapping = THREE.NoToneMapping;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  view.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
  const camera = new THREE.PerspectiveCamera(16, 1, 1, 1000);
  scene.add(new THREE.HemisphereLight(0xfffaf0, 0xb8a98f, 0.35));
  const sun = new THREE.DirectionalLight(0xfff3df, 2.1);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.bias = -0.0004;
  sun.shadow.normalBias = 0.02;
  scene.add(sun, sun.target);

  // White-painted shelving.
  // A shade warmer than the page, so the board reads against the cream background.
  const paint = new THREE.MeshStandardMaterial({ color: 0xe9e4d8, roughness: 0.6, envMapIntensity: 0.5 });
  const pages = new THREE.MeshStandardMaterial({ map: tex(pageCanvas()), roughness: 0.9, envMapIntensity: 0.4 });
  const covers = new Map();
  const coverMat = (hex, hard) => {
    const key = hex + (hard ? 'h' : 'p');
    if (!covers.has(key)) {
      covers.set(key, new THREE.MeshStandardMaterial({
        color: hex, roughness: hard ? 0.85 : 0.6, envMapIntensity: 0.5,
      }));
    }
    return covers.get(key);
  };

  // One mesh per book, built once; a resize only moves them.
  // A marker card: a memo card (3 × 5 in) standing upright on the board, in front of the books,
  // with the letter large on its face. Not hoverable: it isn't a book.
  function markerCard(b, i) {
    const w = Math.round(b.cardWidth * PPI);
    const h = Math.round(b.height * PPI);
    const c = canvasOf(w, h);
    const x = c.getContext('2d');
    x.fillStyle = '#fbf8ef';
    x.fillRect(0, 0, w, h);
    x.fillStyle = '#4a3f33';
    x.font = `600 ${h * 0.7}px Georgia, "Times New Roman", serif`;
    x.textAlign = 'center';
    x.textBaseline = 'middle';
    x.fillText(b.label, w / 2, h / 2 + h * 0.03);
    const paper = new THREE.MeshStandardMaterial({ color: 0xf6f2e6, roughness: 0.9, envMapIntensity: 0.4 });
    const front = new THREE.MeshStandardMaterial({ map: tex(c), roughness: 0.9, envMapIntensity: 0.4 });
    // Box faces: +x, -x, +y, -y, +z (the letter), -z. The card is wide in x and tall in y, thin in z.
    const card = new THREE.Mesh(new THREE.BoxGeometry(b.cardWidth, b.height, b.width), [paper, paper, paper, paper, front, paper]);
    card.receiveShadow = true;
    const group = new THREE.Group();
    group.add(card);
    group.userData = { offset: 0, target: 0, index: i, isBook: false };
    scene.add(group);
    return group;
  }

  const meshes = data.map((b, i) => {
    if (b.marker) return markerCard(b, i);
    const hard = b.binding === 'hardcover';
    const cover = coverMat(b.spine, hard);
    const asset = assets[i];   // loaded before the first frame: no texture is swapped in later
    const sc = spineCanvas(b, asset ? asset.strip : null);
    const sMap = tex(sc);
    const spine = new THREE.MeshStandardMaterial({
      map: sMap, roughness: hard ? 0.8 : 0.45, envMapIntensity: 0.5,
    });
    // One shell per book, as on a real paperback: the spine is the front face and the covers are the
    // side faces, so the spine sits exactly on the covers. Box faces: +x, -x (covers), +y (pages), -y, +z (spine), -z.
    const group = new THREE.Group();
    group.userData = { offset: 0, target: 0, index: 0, isBook: true };
    // Softer edges: a visible curve on the spine's corners (hardcovers round more than paperbacks).
    const radius = hard ? Math.min(0.09, b.thickness * 0.4) : Math.min(0.05, b.thickness * 0.35);
    // More segments round the corners more smoothly: with 4, each corner is a few flat facets whose
    // normals catch the light in alternating bands, which read as dashed seams while the view moves.
    const geo = new RoundedBoxGeometry(b.thickness, b.height, b.width, 4, radius);
    const front = asset ? new THREE.MeshStandardMaterial({ map: tex(asset.img), roughness: 0.6, envMapIntensity: 0.5 }) : cover;
    const block = new THREE.Mesh(geo, [front, cover, pages, cover, spine, cover]);
    // Books don't cast shadows: a slid-out book threw a hard band across its neighbour.
    block.castShadow = false;
    // Books don't receive shadows either: on the grazing edges of the spine and covers the shadow map
    // left dashed seams (shadow acne), so the books are lit without shadow and the shelf keeps its board shadow.
    block.receiveShadow = false;
    group.add(block);
    // Sticky tabs: one per highlight. Each stands up out of the top edge, its face
    // lying in the same plane as the pages (parallel to the covers), so it reads as a tab on the pages.
    const tabs = b.highlights || 0;   // exactly one tab per highlight
    const rnd = seeded(b.id);
    const tabColors = [0xf4d35e, 0xe76f8a, 0x7fb3d5, 0x9bc53d, 0xf29e4c];
    for (let k = 0; k < tabs; k++) {
      // Each tab differs: thickness, width and how far it sticks out all vary.
      const tabT = 0.006 + rnd() * 0.004;   // about the thickness of paper
      const tabD = Math.min(0.7 + rnd() * 0.9, b.width * 0.95);
      const tabH = 0.3 + rnd() * 0.5;
      const tab = new THREE.Mesh(
        new THREE.BoxGeometry(tabT, tabH, tabD),
        new THREE.MeshStandardMaterial({ color: tabColors[Math.floor(rnd() * tabColors.length)], roughness: 0.5, envMapIntensity: 0.4 }));
      tab.position.set((rnd() - 0.5) * Math.max(0, b.thickness - 0.1), b.height / 2 + tabH * 0.35, (rnd() - 0.5) * Math.max(0, b.width - tabD));
      tab.rotation.x = (rnd() - 0.5) * 0.2;
      tab.castShadow = true;
      group.add(tab);
    }
    scene.add(group);
    return group;
  });

  const frame = new THREE.Group();
  scene.add(frame);
  let parts = [];
  let yearMarks = [];   // { x, el }: a year marker's place on the bay and its label (#40)
  let unit = 1, H = 1, dist = 1;
  let hovered = null;

  // The first book of each year of reading gets a marker and a little air before it; a new shelf starts one too.
  function markStarts(gapAt) {
    const s = new Set();
    data.forEach((b, i) => {
      if (b.marker || !b.year) return;
      const prev = data[i - 1];
      if (i === 0 || i === gapAt || !prev || prev.marker || prev.year !== b.year) s.add(i);
    });
    return s;
  }
  // The shelf (Fiction or Non-Fiction) comes first, so the same year can appear once per shelf.
  function yearLabel(year, fiction, first) {
    const el = document.createElement('div');
    el.className = first ? 'shelf-year first' : 'shelf-year';   // the first marker of each shelf is inverted
    el.textContent = `${fiction ? 'Fiction' : 'Non-Fiction'} ${year}`;
    (document.getElementById('shelf-years') || view).appendChild(el);
    return el;
  }

  // Year markers stick to the left edge while their year is still on the bay: the marker of
  // the year at the left edge stays there, and the next year pushes it out (like a sticky
  // section heading). The strip above the shelf keeps them in view while the page scrolls.
  function placeYearMarks(W) {
    const EDGE = 8, PUSH = 6;
    const centre = yearMarks.map((m) => {
      const v = new THREE.Vector3(m.x, FLOOR_T, -SETBACK).project(camera);
      return (v.x + 1) / 2 * W;
    });
    const lefts = new Array(yearMarks.length);
    for (let k = yearMarks.length - 1; k >= 0; k--) {
      const w = yearMarks[k].el.offsetWidth;
      let left = Math.max(centre[k] - w / 2, EDGE);            // on its book, or stuck to the edge
      if (k + 1 < yearMarks.length) left = Math.min(left, lefts[k + 1] - w - PUSH);   // pushed by the next year
      lefts[k] = left;
    }
    yearMarks.forEach((m, k) => {
      m.el.style.left = lefts[k] + 'px';
      m.el.style.visibility = lefts[k] < EDGE ? 'hidden' : '';   // gone once the next year has pushed it out
    });
  }

  // The bay: one row of books on one shelf, as long as the books need.
  function layout() {
    const W = view.clientWidth;
    if (!W) return;
    const gap = 0.01;   // books stand pushed together, as on a real shelf
    // One continuous shelf: fiction first, a small gap, then the non-fiction (the data is already in that order).
    const ROW_H = SHELF_H + FLOOR_T;
    const SECTION_GAP = 2.0;   // inches between the fiction and the non-fiction
    const sectionStart = data.findIndex((b) => b.shelf !== 1 && !b.marker);
    const gapAt = data.some((b) => b.shelf === 1) && sectionStart > 0 ? sectionStart : -1;
    const yStarts = markStarts(gapAt);
    let total = 0;
    data.forEach((b, i) => {
      if (i > 0 && yStarts.has(i)) total += YEAR_GAP;
      total += b.thickness + gap;
      if (i === gapAt) total += SECTION_GAP;
    });
    unit = total - gap + 2 * PAD;
    const rows = 1;
    H = rows * ROW_H;
    const Hpx = Math.round(H * SCREEN_PPI);
    renderer.setSize(W, Hpx);
    view.style.height = Hpx + 'px';
    track.style.width = Math.ceil(unit * SCREEN_PPI) + 'px';

    yearMarks.forEach((m) => m.el.remove());
    yearMarks = [];
    parts.forEach((p) => { frame.remove(p); p.geometry.dispose(); });
    parts = [];
    const add = (geo, mat, x, y, z) => {
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, y, z);
      m.castShadow = true;
      m.receiveShadow = true;
      frame.add(m);
      parts.push(m);
    };
    // One board per shelf: no ends or back, so the books stand in open air.
    // The board reaches 2.5 in past the books' front edge, so the books sit well back from it.
    const BOARD_FRONT = 2.5;
    add(new THREE.BoxGeometry(unit, FLOOR_T, DEPTH + BOARD_FRONT), paint, 0, FLOOR_T / 2, (BOARD_FRONT - DEPTH) / 2);

    let cursor = -unit / 2 + PAD;
    data.forEach((b, i) => {
      const m = meshes[i];
      if (i === gapAt) cursor += SECTION_GAP;
      if (i > 0 && yStarts.has(i)) cursor += YEAR_GAP;
      const x = cursor;
      if (yStarts.has(i)) yearMarks.push({ x: x + b.thickness / 2, el: yearLabel(b.year, b.shelf === 1, i === 0 || i === gapAt) });
      const boardTop = FLOOR_T;
      m.userData.index = i;
      // A marker card stands forward of the books, so you see its letter; a book sits behind the front edge.
      m.userData.base = b.marker
        ? { x: x + b.thickness / 2, y: boardTop + b.height / 2, z: -0.3 }
        : { x: x + b.thickness / 2, y: boardTop + b.height / 2, z: -(SETBACK + (seeded(b.id)() - 0.5) * 0.7) - b.width / 2 };   // each book stands a little differently back
      m.position.set(m.userData.base.x, m.userData.base.y, m.userData.base.z + m.userData.offset);
      cursor += b.thickness + gap;
    });

    // Camera: the shelf's height fills the view; the distance follows from the field of view.
    const fov = camera.fov * Math.PI / 180;
    // Fit the height exactly: the visible width then matches the scroll track (a margin here shifted the left edge).
    dist = (H / 2) / Math.tan(fov / 2);
    camera.aspect = W / Hpx;
    // A near plane at 1 in left the depth buffer too coarse at this distance: the spine and cover edges z-fought
    // (dashed seams). Nothing is closer than about dist - 3 in, so a near plane at 40% of the distance is safe.
    camera.near = dist * 0.4;
    camera.far = dist * 4;
    camera.updateProjectionMatrix();

    sun.position.set(-unit * 0.2, H * 1.4, 30);
    sun.target.position.set(0, H / 2, -DEPTH / 2);
    sun.target.updateMatrixWorld();
    const s = sun.shadow.camera;
    s.left = -unit / 2 - 3; s.right = unit / 2 + 3;
    s.top = H / 2 + 3; s.bottom = -H / 2 - 3;
    s.near = 1; s.far = dist * 4;
    s.updateProjectionMatrix();
    updateView();
  }

  // The view follows the horizontal scroll, from a fixed slight top-down angle.
  function updateView() {
    const W = view.clientWidth;
    const cx = -unit / 2 + (stage.scrollLeft + W / 2) / SCREEN_PPI;
    camera.position.set(cx, H / 2 + TOP_DOWN * dist, dist);
    camera.lookAt(cx, H / 2, -DEPTH / 2);
    placeYearMarks(W);   // year markers follow their books, and stick sideways
    render();
  }

  function render() { renderer.render(scene, camera); }

  function tick() {
    let moving = false;
    for (const m of meshes) {
      if (!m.userData.base) continue;
      const d = m.userData.target - m.userData.offset;
      if (Math.abs(d) > 0.005) {
        m.userData.offset = reduceMotion ? m.userData.target : m.userData.offset + d * 0.25;
        moving = true;
      } else {
        m.userData.offset = m.userData.target;
      }
      m.position.z = m.userData.base.z + m.userData.offset;
    }
    updateView();
    if (moving) requestAnimationFrame(tick);
    else animating = false;
  }
  let animating = false;
  function animate() {
    if (!animating) { animating = true; requestAnimationFrame(tick); }
  }

  // Pointer: hover lifts a spine and names the book; a click opens its page;
  const ray = new THREE.Raycaster();
  const ndc = new THREE.Vector2();
  const canvas = renderer.domElement;

  function pick(ev) {
    const r = canvas.getBoundingClientRect();
    ndc.set(((ev.clientX - r.left) / r.width) * 2 - 1, -((ev.clientY - r.top) / r.height) * 2 + 1);
    ray.setFromCamera(ndc, camera);
    const hit = ray.intersectObjects(meshes, true)[0];
    if (!hit) return null;
    let o = hit.object;
    while (o && !o.userData.isBook) o = o.parent;
    return o || null;
  }

  function hover(m, ev) {
    if (m === hovered) return;
    if (hovered) hovered.userData.target = 0;
    hovered = m;
    if (m) m.userData.target = SLIDE * data[m.userData.index].width;
    canvas.style.cursor = m ? 'pointer' : '';
    animate();
  }

  canvas.addEventListener('pointermove', (ev) => {
    if (ev.pointerType === 'touch') return;
    const r = canvas.getBoundingClientRect();
    // Hover holds while the pointer is still over the hovered book: a book sliding forward can bring a
    // neighbour under the pointer, and switching back and forth between them is the flicker.
    let m = pick(ev);
    if (hovered && m !== hovered && ray.intersectObject(hovered, true).length) m = hovered;
    hover(m, ev);
    animate();
  });
  canvas.addEventListener('pointerleave', () => hover(null, {}));
  canvas.addEventListener('click', (ev) => {
    const m = pick(ev);
    // A click opens the book's page in a new tab, so the shelf stays where it is.
    if (m) window.open(data[m.userData.index].href, '_blank', 'noopener');
  });
  stage.addEventListener('scroll', () => updateView(), { passive: true });

  let raf = 0;
  const onResize = () => { cancelAnimationFrame(raf); raf = requestAnimationFrame(layout); };
  new ResizeObserver(onResize).observe(stage);
  layout();
  stage.dataset.ready = 'true';
}

function start() {
  const stage = document.getElementById('shelf');
  const el = document.getElementById('shelf-data');
  if (!stage || !el) return;
  const data = JSON.parse(el.textContent);
  if (!data.length) return;
  measureSeries(data);
  // The shelf is drawn once every cover is in (or after 20 s), so nothing is swapped in on screen later.
  const loading = document.createElement('div');
  loading.className = 'shelf-loading';
  stage.appendChild(loading);
  preload(data, loading).then((assets) => {
    try {
      main(stage, data, assets);
    } catch (err) {
      // No WebGL: the list under the shelf still has every book.
      console.warn('bookshelf: 3D view unavailable', err);
      stage.replaceChildren();
    }
    loading.remove();
  });
}
start();